//SPDX-License-Identifier: Unlicense

// @title: Monster Mobs
// @author: Monster Mobs Team

pragma solidity ^0.8.0;

import "src/hardhat/console.sol";

import "src/@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "src/@openzeppelin/contracts/token/ERC721/extensions/ERC721Burnable.sol";
import "src/@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "src/@openzeppelin/contracts/token/ERC721/extensions/ERC721Pausable.sol";
import "src/@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "src/@openzeppelin/contracts/access/Ownable.sol";
import "src/@openzeppelin/contracts/utils/math/SafeMath.sol";
import "src/@openzeppelin/contracts/utils/Counters.sol";

contract MonsterMobs is
  ERC721Enumerable,
  Ownable,
  ERC721Burnable,
  ERC721Pausable
{
  using SafeMath for uint256;
  using Counters for Counters.Counter;

  Counters.Counter private _tokenIdTracker;
  bool private presale;
  bool private sale;

  uint256 public constant MAX_ITEMS = 7777;
  uint256 public constant MAX_PRESALE_ITEMS = 777;
  uint256 public constant MAX_RESERVE = 100;
  uint256 public PRICE = 7E16; // 0.07 ETH
  uint256 public constant RENAME_PRICE = 1E16; // 0.01 ETH
  uint256 public constant MAX_MINT = 20;
  uint256 public constant MAX_MINT_PRESALE = 7;
  address public constant creatorAddress =
    0x3587471Eca4f5A0c26E3771a3790296FD32e5612;
  address public constant artistAddress =
    0xf1B943A3E25db879C1BE6AFc15145Ade18402BFF;
  address public constant devAddress =
    0xc4F2F2fcDe383EB86b697422fDdD46FeD89579D7;
  string public baseTokenURI;
  string public PROVENANCE_HASH = "";
  uint256 public REVEAL_TIMESTAMP;
  uint256 public startingIndexBlock;
  uint256 public startingIndex;

  event CreateMonster(uint256 indexed id);
  event AttributeChanged(uint256 indexed _tokenId, string _key, string _value);

  constructor(string memory baseURI) ERC721("MONSTER MOBS", "MONSTERMOBS") {
    setBaseURI(baseURI);
    pause(true);
    presale = false;
    sale = false;
    REVEAL_TIMESTAMP = block.timestamp + (86400 * 7);
  }

  modifier saleIsOpen() {
    require(_totalSupply() <= MAX_ITEMS, "Sale ended");
    if (_msgSender() != owner()) {
      require(!paused(), "Pausable: paused");
    }
    _;
  }

  function _totalSupply() internal view returns (uint) {
    return _tokenIdTracker.current();
  }

  function totalMint() public view returns (uint256) {
    return _totalSupply();
  }

  function mintReserve(uint256 _count, address _to) public onlyOwner {
    uint256 total = _totalSupply();
    require(total <= MAX_ITEMS, "Sale ended");
    require(total + _count <= MAX_ITEMS, "Max limit");
    for (uint256 i = 0; i < _count; i++) {
      _mintAnElement(_to);
    }
  }

  function presaleMint(address _to, uint256 _count) public payable {
    uint256 total = _totalSupply();
    require(presale == true, "Presale has not yet started");
    require(total <= MAX_PRESALE_ITEMS, "Presale ended");
    require(total + _count <= MAX_PRESALE_ITEMS, "Max limit");
    require(_count <= MAX_MINT_PRESALE, "Exceeds number");
    require(msg.value >= price(_count), "Value below price");

    for (uint256 i = 0; i < _count; i++) {
      _mintAnElement(_to);
    }
  }

  function mint(address _to, uint256 _count) public payable saleIsOpen {
    uint256 total = _totalSupply();
    require(sale == true, "Sale has not yet started");
    require(total <= MAX_ITEMS, "Sale ended");
    require(total + _count <= MAX_ITEMS, "Max limit");
    require(_count <= MAX_MINT, "Exceeds number");
    require(msg.value >= price(_count), "Value below price");

    for (uint256 i = 0; i < _count; i++) {
      _mintAnElement(_to);
    }

    if (
      startingIndexBlock == 0 &&
      (totalSupply() == MAX_ITEMS || block.timestamp >= REVEAL_TIMESTAMP)
    ) {
      startingIndexBlock = block.number;
    }
  }

  function _mintAnElement(address _to) private {
    uint id = _totalSupply();
    _tokenIdTracker.increment();
    _safeMint(_to, id);
    emit CreateMonster(id);
  }

  function price(uint256 _count) public view returns (uint256) {
    return PRICE.mul(_count);
  }

  function _baseURI() internal view virtual override returns (string memory) {
    return baseTokenURI;
  }

  function setBaseURI(string memory baseURI) public onlyOwner {
    baseTokenURI = baseURI;
  }

  function setMintPrice(uint256 _price) external onlyOwner {
    PRICE = _price;
  }

  /*
   * Set provenance once it's calculated
   */
  function setProvenanceHash(string memory _provenanceHash) external onlyOwner {
    PROVENANCE_HASH = _provenanceHash;
  }

  /**
   * Set the starting index for the collection
   */
  function setStartingIndex() external {
    require(startingIndex == 0, "Starting index is already set");
    require(startingIndexBlock != 0, "Starting index block must be set");

    startingIndex = uint256(blockhash(startingIndexBlock)) % MAX_ITEMS;
    // Just a sanity case in the worst case if this function is called late (EVM only stores last 256 block hashes)
    if (block.number.sub(startingIndexBlock) > 255) {
      startingIndex = uint256(blockhash(block.number - 1)) % MAX_ITEMS;
    }
    // Prevent default sequence
    if (startingIndex == 0) {
      startingIndex = startingIndex.add(1);
    }
  }

  /**
   * Set the starting index block for the collection, essentially unblocking
   * setting starting index
   */
  function emergencySetStartingIndexBlock() external onlyOwner {
    require(startingIndex == 0, "Starting index is already set");

    startingIndexBlock = block.number;
  }

  function walletOfOwner(address _owner)
    external
    view
    returns (uint256[] memory)
  {
    uint256 tokenCount = balanceOf(_owner);

    uint256[] memory tokenIds = new uint256[](tokenCount);
    for (uint256 i = 0; i < tokenCount; i++) {
      tokenIds[i] = tokenOfOwnerByIndex(_owner, i);
    }

    return tokenIds;
  }

  function pause(bool val) public onlyOwner {
    if (val == true) {
      _pause();
      return;
    }
    _unpause();
  }

  function startPresale() public onlyOwner {
    presale = true;
  }

  function startSale() public onlyOwner {
    sale = true;
  }

  function changeAttribute(
    uint256 tokenId,
    string memory key,
    string memory value
  ) public payable {
    address owner = ERC721.ownerOf(tokenId);
    require(_msgSender() == owner, "This is not your Monster.");

    uint256 amountPaid = msg.value;
    require(
      amountPaid == RENAME_PRICE,
      "There is a price for changing your attributes."
    );

    emit AttributeChanged(tokenId, key, value);
  }

  function withdrawAll() public payable onlyOwner {
    uint256 balance = address(this).balance;
    require(balance > 0);
    _widthdraw(devAddress, balance.mul(30).div(100));
    _widthdraw(artistAddress, balance.mul(35).div(100));
    _widthdraw(creatorAddress, address(this).balance);
  }

  function _widthdraw(address _address, uint256 _amount) private {
    (bool success, ) = _address.call{ value: _amount }("");
    require(success, "Transfer failed.");
  }

  function _beforeTokenTransfer(
    address from,
    address to,
    uint256 tokenId
  ) internal virtual override(ERC721, ERC721Enumerable, ERC721Pausable) {
    super._beforeTokenTransfer(from, to, tokenId);
  }

  function supportsInterface(bytes4 interfaceId)
    public
    view
    virtual
    override(ERC721, ERC721Enumerable)
    returns (bool)
  {
    return super.supportsInterface(interfaceId);
  }
}

